import { BooleanColumn, IntegerColumn, ReferenceColumn, StringColumn, Table } from '../../db'

export const sys_ws_version = Table({
    name: 'sys_ws_version',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({}),
        deprecated: BooleanColumn({}),
        is_default: BooleanColumn({}),
        short_description: StringColumn({}),
        version: IntegerColumn({}),
        version_id: StringColumn({}),
        web_service_definition: ReferenceColumn({ referenceTable: 'sys_ws_definition' }),
    },
})
